"""Retain prospective learned-semantic prototype protocol and all signed outcomes."""
import sys
from pathlib import Path
R=Path(__file__).resolve().parents[2];sys.path.insert(0,str(R))
from research.native_event_semantic_prototype_v1.run import D,P,read,put,sha

def main():
 r=read(P/'report.json');s=read(D/'sealed.json');p=read(D/'plan.json');a=p['primary'];pair=r['paired'][a+'-NativeG6'];source=r['paired'][a+'-Source'];controls=['RandomProjectionLoop2','ReversedSemanticLoop2','SharpenOriginal'];sg={g:{arm:sum(100*(x['values'][arm]['t']-x['values']['Source']['t'])for x in r['rows']if x['duration_group']==g)/sum(x['duration_group']==g for x in r['rows'])for arm in p['arms']}for g in r['groups_vs_G6']};put(P/'source_duration_groups.json',sg)
 passed=all(x['mean']>0 for x in [pair['t'],pair['v'],source['t'],source['v']])and pair['t']['improved']>pair['t']['harmed']and all(sg[g][a]>0 for g in sg)and all(r['paired'][a+'-'+b]['t']['mean']>0 for b in controls)
 lines=['# Learned semantic projection and cross-fit prototype loop','','Original frozen SpatialActivation word head is supervised by pooled verb-label BCE. This study observes its pre-mean per-frame logits and 256-dimensional input; it does not use actionness/foreground as new feedback. Dense frame word responses are an extrapolation from pooled training, not calibrated event probabilities. Original full text and all original visual features/time positions remain unchanged. Motion vocabulary34 and appearance vocabulary20; no class-name/annotation vocabulary reads. Learned query-conditioned semantic coordinates are distinct from raw arbitrary 256-dimensional cosine matching.','','NativeG6 soft inclusive interval membership seeds opposite-parity positive/negative class centroids. Expected soft-Bernoulli log-likelihood ratios SUM classes and SUM inclusive interval frames. Exactly TWO rounds, every round anchored to original q0, no cumulative posterior prior, optimizer, learned weights, gain, threshold or abstention. Cross-offset features overlap and q0 uses both offsets: cross-fitting is not independent validation. Class/frame pseudolikelihood independence is not guaranteed.','','Controls: one round; direct same SECOND-round evidence under uniform legal prior; reverse65 semantic rows; fixed Gaussian projection of SAME head input with rank mapping to EXACT per-class real sigmoid histogram; appearance word space; original q0 squared; constant-projection exact NativeG6. All64 active. All64 seal before independent CPU scoring. Full64 hidden/logits/q/Source boxes bitwise; spatial complete boxes/eight observations/DP unchanged. Five CPU tests membership/inclusive endpoints/constant-label invariance/parity isolation/synthetic positive control.','','|Arm|complete vIoU|tIoU|time +/−/=|time harm>5pp|','|---|---:|---:|---:|---:|']
 for arm,m in r['means'].items():
  t=r['paired'].get(arm+'-NativeG6',{}).get('t',{});lines.append(f"|{arm}|{100*m['v']:.4f}|{100*m['t']:.4f}|{t.get('improved',0)}/{t.get('harmed',0)}/{t.get('unchanged',64)}|{t.get('severe_below_minus5pp',0)}|")
 lines+=['',f"Primary−Global6 t{pair['t']['mean']:+.4f}pp CI{pair['t']['CI95']}; v{pair['v']['mean']:+.4f}pp CI{pair['v']['CI95']}.",f"Primary−Source t{source['t']['mean']:+.4f}pp; v{source['v']['mean']:+.4f}pp. Source short{sg['short_le5s'][a]:+.4f}/long{sg['long_gt5s'][a]:+.4f}tpp."]
 for b in controls+['OneStepPrototype','DirectSemanticEvidence','AppearancePrototypeLoop2']:lines.append(f"Primary−{b} t{r['paired'][a+'-'+b]['t']['mean']:+.4f}pp CI{r['paired'][a+'-'+b]['t']['CI95']}.")
 lines+=['','Basic exposed-development screen only; fixed dual-domain recheck required.'if passed else'Not qualified. Do not amplify scores, tune iterations/gain or promote a control post hoc.',f"Study worker{s['seconds']:.2f}s includes load/no-op verification/recording; actual calls{s['counts']}. Deployment would reuse existing Full hidden and add dense word heads/prototype math; this study is not deployment timing. No new RGB/visual encoder/text encoder/expert/observations/optimizer.",f"Official/dense checks{r['checks']} maximum error{r['max_metric_error']:.3g}. [All signed outcomes](signed.tsv), [severe tails](severe_declines.tsv), [Source duration groups](source_duration_groups.json), [fixed protocol](protocol.json).",'','Original source [SpatialActivation](https://github.com/HengLan/TA-STVG/blob/904ad0c344eb12fe34513f97a33f93118f6d3be4/models/grounding_model/classifier.py) produces head(query).mean(frames). Pooled-label supervision does not establish frame-event discrimination. This is TA-specific learned semantic-interface feasibility, not a universal three-backbone interface or OPD/DSE reproduction.']
 (P/'ANALYSIS.md').write_text('\n'.join(lines)+'\n');put(P/'verification.json',dict(queries=64,Fullhidden_logits_q_Sourceboxes_bitwise=64,random_each_class_histogram_exact=64,constant_feature_q_interval_finalbox_exact=64,all64_seal_before_GT=True,paper_sources_unchanged=48,provider_sources_unchanged=434,CPU_tests=5,checks=r['checks'],max_metric_error=r['max_metric_error'],basic_development_screen=passed,promoted=False,seal_sha256=sha(D/'sealed.json')))
if __name__=='__main__':main()
